package com.backend.gapfinder.view.dto.requests;

import java.time.LocalDateTime;

import lombok.Data;

// Body of POST /users/{userId}/study-mode (the user is the one in the path, checked against the token)
@Data
public class StudyPeriodRequest {

    // Start of the study period (local date and time, without time zone)
    private LocalDateTime startTime;

    // End of the study period (after the start, at most 12 hours later)
    private LocalDateTime endTime;

    // Gap the student chose to hide (optional, informational only)
    private Long gapId;

    // Id generated by the app (UUID) so a retried request is not duplicated
    private String clientId;
}
